import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public class Demo {
    public static void main(String[] args) throws Exception {
        // AVANT Java 18 : le charset dependait de la machine.
        // Pour etre sur, on devait TOUJOURS le preciser a la main :
        String texte1 = Files.readString(Path.of("notes.txt"), StandardCharsets.UTF_8);

        // DEPUIS Java 18 : sans rien preciser, c'est deja de l'UTF-8 partout.
        String texte2 = Files.readString(Path.of("notes.txt"));

        // Les deux lignes donnent maintenant le meme resultat, sur toute machine.
        System.out.println(texte1.equals(texte2)); // true
    }
}

import com.sun.net.httpserver.SimpleFileServer;
import java.net.InetSocketAddress;
import java.nio.file.Path;

public class Demo {
    public static void main(String[] args) {
        // On choisit l'adresse (localhost) et le port (8000).
        var adresse = new InetSocketAddress("127.0.0.1", 8000);
        // Le dossier dont on veut servir les fichiers.
        var dossier = Path.of("mon-site").toAbsolutePath();

        // createFileServer construit un serveur tout pret (Java 18+).
        var serveur = SimpleFileServer.createFileServer(
            adresse, dossier, SimpleFileServer.OutputLevel.VERBOSE);

        serveur.start(); // Le serveur ecoute maintenant les demandes.
        System.out.println("Fichiers servis sur http://127.0.0.1:8000/");
        // Pour un vrai usage de test : on l'arreterait plus tard avec serveur.stop(0).
    }
}

import java.util.HexFormat;

public class Demo {
    public static void main(String[] args) {
        // On recupere une instance reutilisable (Java 17+).
        HexFormat hex = HexFormat.of();

        byte[] donnees = { 1, 10, (byte) 255 };

        // Octets -> texte hexadecimal. Chaque octet devient 2 caracteres.
        String texte = hex.formatHex(donnees);
        System.out.println(texte); // 010aff

        // Texte hexadecimal -> octets (le chemin inverse).
        byte[] relus = hex.parseHex("010aff");
        System.out.println(relus.length);        // 3
        System.out.println(relus[2] & 0xff);     // 255
    }
}

import java.util.HexFormat;

public class Demo {
    public static void main(String[] args) {
        byte[] donnees = { (byte) 171, (byte) 205, (byte) 239 }; // ab cd ef

        // Style compact et en minuscules (le defaut).
        System.out.println(HexFormat.of().formatHex(donnees)); // abcdef

        // Avec un separateur ":" entre les octets et en MAJUSCULES.
        HexFormat lisible = HexFormat.ofDelimiter(":").withUpperCase();
        System.out.println(lisible.formatHex(donnees)); // AB:CD:EF

        // Un seul octet a la fois, bien formate (toujours 2 caracteres).
        System.out.println(HexFormat.of().toHexDigits((byte) 5)); // 05
    }
}

public class Demo {
    public static void main(String[] args) {
        // Math.clamp(valeur, min, max) : ramene valeur entre min et max (Java 21+).
        System.out.println(Math.clamp(150, 0, 100)); // 100 (trop grand -> max)
        System.out.println(Math.clamp(-20, 0, 100)); // 0   (trop petit -> min)
        System.out.println(Math.clamp(42, 0, 100));  // 42  (deja dans l'intervalle)

        // Sans Math.clamp, il fallait ecrire a la main :
        int volume = -20;
        int borne = Math.max(0, Math.min(100, volume));
        System.out.println(borne); // 0, mais moins lisible qu'un simple clamp
    }
}

import java.util.List;

public class Demo {
    public static void main(String[] args) {
        // isBlank : vide ou seulement des espaces ?
        System.out.println("   ".isBlank()); // true
        System.out.println("abc".isBlank());  // false

        // repeat : repeter une chaine, utile pour un separateur visuel.
        System.out.println("=".repeat(10)); // ==========

        // List.of : une liste non modifiable, creee en une ligne.
        List<String> couleurs = List.of("violet", "bleu", "blanc");
        System.out.println(couleurs); // [violet, bleu, blanc]
    }
}

